  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 42, 'mcq_single', $q$Un poste ne parvient pas à joindre sa passerelle, alors que les autres postes branchés sur le même switch fonctionnent. Où cherchez-vous en priorité ?$q$, $q$[{"id": "a", "text": "Sur le pare-feu Internet, qui filtre peut-être le trafic de ce poste"}, {"id": "b", "text": "Sur le serveur DNS, qui ne résout peut-être plus l'adresse de la passerelle"}, {"id": "c", "text": "Sur le poste lui-même : câble, port du switch, configuration IP, VLAN du port"}, {"id": "d", "text": "Chez le fournisseur d'accès à Internet, qui coupe peut-être ce poste"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q42') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["c"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 42, 'mcq_single', $q$Un seul utilisateur n'arrive plus à ouvrir un site web interne, alors que ses collègues du même service y accèdent sans problème. Où cherchez-vous en priorité ?$q$, $q$[{"id": "a", "text": "Sur le serveur web interne, qui est peut-être arrêté"}, {"id": "b", "text": "Sur le pare-feu Internet de l'entreprise"}, {"id": "c", "text": "Sur le serveur DNS interne, qui ne résout plus le nom du site"}, {"id": "d", "text": "Sur le poste : navigateur, proxy, fichier hosts, cache DNS"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q42') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["d"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 43, 'mcq_single', $q$Tous les utilisateurs d'un étage perdent le réseau, alors que le reste du bâtiment fonctionne. Quelle est la cause la plus probable ?$q$, $q$[{"id": "a", "text": "Une panne du serveur DNS central de l'entreprise"}, {"id": "b", "text": "Une coupure chez le fournisseur d'accès à Internet"}, {"id": "c", "text": "Un problème sur le switch de l'étage ou sur sa liaison montante"}, {"id": "d", "text": "Des mots de passe expirés pour les utilisateurs de cet étage"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q43') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["c"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 43, 'mcq_single', $q$Un matin, plus aucun poste de l'entreprise n'accède à Internet, mais les serveurs internes (fichiers, intranet) restent joignables. Quelle est la cause la plus probable ?$q$, $q$[{"id": "a", "text": "Un problème sur le switch d'un des étages du bâtiment"}, {"id": "b", "text": "Une panne du routeur Internet ou de la liaison opérateur"}, {"id": "c", "text": "Des cartes réseau défectueuses sur l'ensemble des postes"}, {"id": "d", "text": "Une GPO qui aurait modifié les adresses IP de tous les postes"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q43') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["b"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 44, 'mcq_single', $q$Une GPO ne semble pas s'appliquer sur un poste. Quelle commande permet de voir les GPO effectivement appliquées ?$q$, $q$[{"id": "a", "text": "ipconfig /all"}, {"id": "b", "text": "gpupdate /force"}, {"id": "c", "text": "gpresult /r"}, {"id": "d", "text": "netstat -an"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q44') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["c"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 44, 'mcq_single', $q$Un poste n'arrive pas à joindre le contrôleur de domaine par son nom, dc01.lab.local. Quelle commande permet de tester la résolution de ce nom auprès du serveur DNS ?$q$, $q$[{"id": "a", "text": "gpupdate /force"}, {"id": "b", "text": "ipconfig /flushdns"}, {"id": "c", "text": "netstat -ano"}, {"id": "d", "text": "nslookup dc01.lab.local"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q44') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["d"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 45, 'mcq_single', $q$Vous recevez ces demandes en même temps. Laquelle traitez-vous en premier ?$q$, $q$[{"id": "a", "text": "Un utilisateur demande un second écran"}, {"id": "b", "text": "La messagerie est en panne pour toute l'entreprise"}, {"id": "c", "text": "La souris d'un utilisateur fonctionne mal"}, {"id": "d", "text": "Une imprimante de service en panne, une autre imprimante est disponible à côté"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q45') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["b"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 45, 'mcq_single', $q$Plusieurs tickets arrivent au support au même moment. Lequel prenez-vous en charge en premier ?$q$, $q$[{"id": "a", "text": "Un nouvel arrivant demande un logiciel pour la semaine prochaine"}, {"id": "b", "text": "Un utilisateur cherche un fichier supprimé il y a un mois"}, {"id": "c", "text": "Le serveur de paie est inaccessible la veille du versement des salaires"}, {"id": "d", "text": "Le Wi-Fi est lent en salle de réunion, mais le filaire fonctionne"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q45') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["c"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 46, 'mcq_single', $q$Au démarrage de session, un poste affiche : « The trust relationship between this workstation and the primary domain failed. » Que signifie ce message ?$q$, $q$[{"id": "a", "text": "Le serveur DNS est injoignable depuis le poste au moment de la connexion"}, {"id": "b", "text": "Le mot de passe de l'utilisateur a expiré et doit être changé"}, {"id": "c", "text": "La licence Windows du poste a expiré et doit être réactivée"}, {"id": "d", "text": "La relation d'approbation entre le poste et le domaine est rompue (problème de compte ordinateur)"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q46') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["d"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 46, 'mcq_single', $q$À l'ouverture de session, un poste du domaine affiche : « Il n'y a actuellement aucun serveur d'ouverture de session disponible pour traiter la demande d'ouverture de session. » Que signifie ce message ?$q$, $q$[{"id": "a", "text": "Le mot de passe saisi par l'utilisateur est incorrect ou a expiré"}, {"id": "b", "text": "Le poste ne parvient à joindre aucun contrôleur de domaine (réseau ou DNS)"}, {"id": "c", "text": "La licence Windows du poste a expiré et doit être réactivée"}, {"id": "d", "text": "Le profil local de l'utilisateur est corrompu et doit être recréé"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q46') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["b"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 47, 'mcq_single', $q$Une connexion SSH vers un serveur échoue avec le message « Connection refused ». Que peut-on en déduire ?$q$, $q$[{"id": "a", "text": "Le serveur est joignable, mais aucun service n'écoute sur ce port ou un pare-feu rejette la connexion"}, {"id": "b", "text": "Le serveur n'existe pas ou est éteint"}, {"id": "c", "text": "Le mot de passe ou la clé SSH sont incorrects"}, {"id": "d", "text": "Le nom du serveur n'est pas résolu par le DNS"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q47') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["a"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 47, 'mcq_single', $q$En vous connectant en SSH à un serveur, vous obtenez l'avertissement « WARNING: REMOTE HOST IDENTIFICATION HAS CHANGED! ». Que peut-on en déduire ?$q$, $q$[{"id": "a", "text": "La clé d'hôte du serveur a changé : réinstallation ou possible interception"}, {"id": "b", "text": "Le mot de passe de votre compte sur le serveur a été modifié par l'administrateur"}, {"id": "c", "text": "Le service SSH n'écoute plus sur le port 22 et a été déplacé sur un autre port"}, {"id": "d", "text": "Votre clé SSH privée a expiré et doit être régénérée sur votre poste"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q47') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["a"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 48, 'mcq_multi', $q$Avant de modifier la configuration d'un switch en production, quelles précautions prenez-vous (plusieurs réponses possibles) ?$q$, $q$[{"id": "a", "text": "Planifier un créneau et prévenir les utilisateurs concernés"}, {"id": "b", "text": "Appliquer directement la modification pour gagner du temps"}, {"id": "c", "text": "Sauvegarder la configuration actuelle"}, {"id": "d", "text": "Prévoir une procédure de retour arrière"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q48') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["a", "c", "d"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 48, 'mcq_multi', $q$Vous devez redémarrer un serveur de fichiers en production pour appliquer des mises à jour. Quelles précautions prenez-vous (plusieurs réponses possibles) ?$q$, $q$[{"id": "a", "text": "Vérifier qu'une sauvegarde récente et restaurable existe"}, {"id": "b", "text": "Prévenir les utilisateurs et choisir un créneau de faible activité"}, {"id": "c", "text": "Redémarrer en pleine journée pour voir tout de suite les problèmes"}, {"id": "d", "text": "Contrôler après redémarrage que les services et partages répondent"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q48') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["a", "b", "d"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 49, 'mcq_single', $q$Les utilisateurs signalent que le serveur de fichiers est très lent tous les jours entre 12 h et 13 h, et seulement sur ce créneau. Quelle hypothèse vérifiez-vous en premier ?$q$, $q$[{"id": "a", "text": "Une sauvegarde ou une tâche planifiée qui s'exécute sur ce créneau"}, {"id": "b", "text": "Une infection par un virus qui se déclenche sur le serveur"}, {"id": "c", "text": "Une panne intermittente du serveur DNS de l'entreprise"}, {"id": "d", "text": "Un câble réseau défectueux entre le serveur et le switch"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q49') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["a"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 49, 'mcq_single', $q$Chaque lundi vers 9 h, de nombreux utilisateurs signalent que l'ouverture de session prend plusieurs minutes ; le reste de la semaine, tout est normal. Quelle hypothèse vérifiez-vous en premier ?$q$, $q$[{"id": "a", "text": "Une surcharge due aux postes qui démarrent et se mettent à jour en même temps"}, {"id": "b", "text": "Un câble réseau défectueux entre le contrôleur de domaine et le switch"}, {"id": "c", "text": "Une panne matérielle du disque dur de chacun des postes concernés"}, {"id": "d", "text": "Un virus programmé pour se déclencher uniquement le lundi matin"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q49') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["a"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 50, 'mcq_single', $q$Un utilisateur ne peut plus ouvrir sa session : « Votre compte a été verrouillé ». Que faites-vous ?$q$, $q$[{"id": "a", "text": "Supprimer son compte et lui en recréer un nouveau avec un mot de passe provisoire"}, {"id": "b", "text": "Le déverrouiller immédiatement pour qu'il puisse travailler, sans autre vérification"}, {"id": "c", "text": "Désactiver le verrouillage des comptes pour tout le monde afin d'éviter que cela se reproduise"}, {"id": "d", "text": "Vérifier son identité, déverrouiller le compte, puis chercher l'origine des échecs (ancien mot de passe enregistré sur un autre appareil, tentative d'attaque)"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q50') returning id into v_q;
  insert into answer_keys(question_id, correct) values (v_q, '["d"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 50, 'mcq_single', $q$Un utilisateur appelle le support pour faire réinitialiser son mot de passe. Vous ne reconnaissez pas sa voix et il insiste sur l'urgence. Que faites-vous ?$q$, $q$[{"id": "a", "text": "Réinitialiser le mot de passe tout de suite et le lui dicter au téléphone"}, {"id": "b", "text": "Vérifier son identité (rappel au numéro de l'annuaire interne) avant de réinitialiser"}, {"id": "c", "text": "Refuser définitivement toute réinitialisation de mot de passe par téléphone"}, {"id": "d", "text": "Envoyer le nouveau mot de passe à l'adresse mail personnelle qu'il vous indique"}]$q$::jsonb, 1, $q$Logique et diagnostic$q$, 'b3-q50') returning id into v_q;
