  insert into question_terminals(question_id, scenario, flag) values (v_q, $q${"user": "tech", "hostname": "srv-fic-01", "home": "/home/tech", "motd": "Ticket #4127 : le serveur de fichiers srv-fic-01 sature et l'équipe compta se plaint.\nLis ~/TICKET.txt, puis remplis les missions. Tape « help » pour la liste des commandes.", "files": {"/home/tech/TICKET.txt": "Ticket #4127, priorité haute\n-----------------------------\n1. Un processus lancé par le compte stagiaire occupe tout le processeur : arrête-le.\n2. Le disque est plein : dans /var/log/app, supprime l'archive qui occupe le plus de place\n   (garde les journaux du jour).\n3. Le dossier /srv/partage/compta est lisible par tout le monde : donne-lui les droits 770.\n4. Cette nuit, un compte a subi de nombreux échecs de connexion SSH (/var/log/auth.log).\n   Écris son nom, seul, dans ~/rapport.txt\n", "/var/log/auth.log": "Oct 30 06:22:51 srv-fic-01 sshd[2038]: Accepted password for a.moreau from 10.20.0.32 port 41482 ssh2\nOct 30 08:36:15 srv-fic-01 sshd[2042]: Accepted password for a.moreau from 10.20.0.59 port 49991 ssh2\nOct 30 06:39:25 srv-fic-01 sshd[2130]: Accepted password for s.benali from 10.20.0.36 port 54057 ssh2\nOct 30 08:39:47 srv-fic-01 sshd[2096]: Accepted password for j.petit from 10.20.0.54 port 42704 ssh2\nOct 30 03:14:22 srv-fic-01 sshd[3012]: Failed password for svc-backup from 10.20.0.66 port 45592 ssh2\nOct 30 06:48:49 srv-fic-01 sshd[2092]: Accepted password for l.garcia from 10.20.0.41 port 44145 ssh2\nOct 30 03:16:55 srv-fic-01 sshd[3019]: Failed password for svc-backup from 10.20.0.66 port 46854 ssh2\nOct 30 07:14:33 srv-fic-01 sshd[2091]: Accepted password for m.durand from 10.20.0.48 port 47084 ssh2\nOct 30 03:19:23 srv-fic-01 sshd[3027]: Failed password for svc-backup from 10.20.0.66 port 54207 ssh2\nOct 30 03:11:10 srv-fic-01 sshd[3005]: Failed password for svc-backup from 10.20.0.66 port 41906 ssh2\nOct 30 07:39:21 srv-fic-01 sshd[2044]: Accepted password for a.moreau from 10.20.