  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 49, 'mcq_single', $q$Depuis ce matin, les utilisateurs reçoivent une alerte de certificat en ouvrant l'intranet. Aucune configuration n'a été modifiée. Que vérifiez-vous en premier ?$q$, $q$[{"id": "a", "text": "Les règles du pare-feu"}, {"id": "b", "text": "La date d'expiration du certificat"}, {"id": "c", "text": "La configuration DHCP"}, {"id": "d", "text": "Une attaque par déni de service"}]$q$::jsonb, 1, $q$Analyse et diagnostic$q$, 'mastere-q49') returning id into v_q;
