  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 49, 'mcq_single', $q$Depuis ce matin, un serveur membre du domaine n'arrive plus à authentifier les utilisateurs et renvoie une erreur Kerberos. Aucune configuration n'a été modifiée. Que vérifiez-vous en premier ?$q$, $q$[{"id": "a", "text": "Les règles du pare-feu local"}, {"id": "b", "text": "La synchronisation de l'horloge du serveur"}, {"id": "c", "text": "La configuration DHCP du serveur"}, {"id": "d", "text": "La taille du journal Sécurité"}]$q$::jsonb, 1, $q$Analyse et diagnostic$q$, 'mastere-q49') returning id into v_q;
