  insert into questions(test_id, position, type, prompt, options, points, domain, variant_group) values (v_test, 50, 'mcq_single', $q$Le SIEM signale qu'un même compte s'est connecté à 9 h 02 depuis Paris, puis à 9 h 10 depuis Singapour. Comment l'interprétez-vous ?$q$, $q$[{"id": "a", "text": "Une panne du SIEM, qui a mal géolocalisé l'une des deux connexions"}, {"id": "b", "text": "Un simple décalage horaire entre les journaux de deux serveurs"}, {"id": "c", "text": "Un « voyage impossible » : on vérifie l'usage d'un VPN, sinon on considère le compte compromis (suspension, réinitialisation, analyse)"}, {"id": "d", "text": "Un comportement normal pour un collaborateur qui voyage beaucoup"}]$q$::jsonb, 1, $q$Analyse et diagnostic$q$, 'mastere-q50') returning id into v_q;
